do $$declare it_u uuid:='98000000-0000-0000-0000-000000000001';other_u uuid:='99000000-0000-0000-0000-000000000001';sid uuid;n1 uuid;n2 uuid;d1 uuid;d2 uuid;n bigint;begin
 perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',it_u::text,false);sid:=public.notification_register_push('https://push.example.test/batch-metrics/1234567890',repeat('g',65),repeat('h',24),null,'Batch Browser','android','جهاز الدفعة');execute'reset role';
 insert into public.notifications(user_id,title,type,category,priority,link,dedupe_key)values(it_u,'دفعة 1','warning','system','high','/it/notifications','batch-metric-1')returning id into n1;insert into public.notifications(user_id,title,type,category,priority,link,dedupe_key)values(it_u,'دفعة 2','warning','system','high','/it/notifications','batch-metric-2')returning id into n2;select id into d1 from public.notification_push_deliveries where notification_id=n1 and subscription_id=sid;select id into d2 from public.notification_push_deliveries where notification_id=n2 and subscription_id=sid;update public.notification_push_deliveries set status='failed',attempts=3,last_http_status=503 where id in(d1,d2);
 perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',it_u::text,false);select count(*)into n from public.notification_push_metrics(24)where total>=2 and failed>=2 and average_attempts>0;if n<1 then raise exception'PUSH_METRICS_FAIL';end if;if public.notification_push_batch_retry(array[d1,d2],'إعادة جماعية بعد معالجة المصدر')<>2 then raise exception'PUSH_BATCH_RETRY_FAIL';end if;execute'reset role';select count(*)into n from public.notification_push_deliveries where id in(d1,d2)and status='pending'and attempts=0;if n<>2 then raise exception'PUSH_BATCH_STATE_FAIL';end if;select count(*)into n from public.notification_push_admin_actions where delivery_id in(d1,d2)and action='retry_delivery';if n<>2 then raise exception'PUSH_BATCH_AUDIT_FAIL';end if;
 perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',it_u::text,false);begin perform public.notification_push_batch_retry(array[d1,d1],'تكرار غير صالح');raise exception'PUSH_BATCH_DUPLICATE_ACCEPTED';exception when others then if sqlerrm='PUSH_BATCH_DUPLICATE_ACCEPTED'then raise;end if;if sqlerrm not like'%PUSH_BATCH_RETRY_INVALID%'then raise;end if;end;perform set_config('request.jwt.claim.sub',other_u::text,false);begin perform public.notification_push_metrics(24);raise exception'PUSH_METRICS_ISOLATION_ACCEPTED';exception when others then if sqlerrm='PUSH_METRICS_ISOLATION_ACCEPTED'then raise;end if;if sqlerrm not like'%PUSH_OPERATIONS_FORBIDDEN%'then raise;end if;end;
 raise notice'✅ الجولة 17: مؤشرات النجاح والتفاعل ومتوسط المحاولات والإعادة الجماعية والحدود والعزل ناجحة';end$$;
